{
  "description": "Shows rotating study tips beside the spinner",
  "modules": [
    "./register.js"
  ]
}

// Rotates a study tip beside the spinner each time Claude uses a tool.
const tips = [
  'Explain it aloud in your own words',
  'Take a 5 minute break every 25 minutes',
  'Try to answer before reading the solution',
  'Write one question about what you just learned'
]
let i = 0

export function register(on) {
  on('tool.call', async ($, e, next) => {
    i = (i + 1) % tips.length
    $.ui.invalidate('ui.render')
    return next(e)
  })
  on('ui.render', { component: 'Spinner' }, async ($, e, next) => {
    return next({ ...e, props: { ...e.props, suffix: ' · tip: ' + tips[i] + '…' } })
  })
}

