let timer = null

export function register(on) {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'break', description: 'Start a rest timer', argumentHint: '[minutes]', immediate: true })
    return next(e)
  })
  on('command.run', { command: 'break' }, async ($, e) => {
    const minutes = Number(e.args) > 0 ? Number(e.args) : 5
    if (timer) timer.cancel()
    timer = $.clock.after(minutes * 60 * 1000, () => {
      $.ui.toast('Break over. Ready for the next task?')
    })
    return { text: 'Rest for ' + minutes + ' minutes' }
  })
}

