  "description": "Set an exam date with /exam and see the days remaining in the status line under the prompt",
  "author": {
    "name": "Promptzyra"
  }
}

{
  "description": "Set an exam date with /exam and see the days remaining in the status line under the prompt",
  "modules": [
    "./register.js"
  ]
}

let examDate = null

function show($) {
  if (!examDate) return
  const days = Math.ceil((examDate.getTime() - Date.now()) / 86400000)
  $.ui.status('exam in ' + days + ' day(s)')
}

export function register(on) {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'exam', description: 'Set the exam date', argumentHint: '[YYYY-MM-DD]', immediate: true })
    $.clock.every(60 * 60 * 1000, () => show($))
    return next(e)
  })
  on('command.run', { command: 'exam' }, async ($, e) => {
    const date = new Date(e.args)
    if (!e.args || isNaN(date.getTime())) return { text: 'Usage: /exam 2027-03-15' }
    examDate = date
    show($)
    return { text: 'Exam date set to ' + e.args }
  })
}

